func DispatchConstants(d, p, m byte, vec *ConstantsStateVector) error {
	identity, err := ResolveConstantsIdentity(d, p, m)
	if err != nil {
		return err
	}
	handler := ConstantsTable[identity.Code]
	if handler == nil {
		return errors.New("constants kernel not initialized")
	}
	return handler(identity, vec)
}

func GetConstantsExecutionCount(code uint16) uint64 {
	if code >= 1000 {
		return 0
	}
	return atomic.LoadUint64(&ConstantsMetrics[code])
}
